/* Practice questions for "1 week study for permit".
 *
 * Written from the Pennsylvania Driver's Manual (PUB 95, online edition) and shaped after
 * PennDOT's own review questions for chapters 2, 3 and 4. They are not PennDOT's test questions.
 *
 * Each row: [id, topic, question, [answers], why, sign id].
 * The FIRST answer is the correct one. The app shuffles the answers.
 * A row with a sign id shows that sign above the question.
 */
const PERMIT_QUESTIONS = [
  /* ---------- signs ---------- */
  ['s01', 'signs', 'What must you do at this sign?', ['Stop completely, check for pedestrians and cross traffic, then go when clear', 'Slow down without coming to a complete stop', 'Stop completely and wait for a green light', 'Slow down and check for traffic'], 'A STOP sign always means a complete stop. Slowing down without stopping is illegal.', 'stop'],
  ['s02', 'signs', 'Which sign is the only one with eight sides?', ['STOP', 'YIELD', 'DO NOT ENTER', 'SCHOOL'], 'The STOP sign is the only octagon on the road, so you can recognise it by shape alone.'],
  ['s03', 'signs', 'What does this sign tell you to do?', ['Slow down and give the right-of-way; stop only if necessary', 'Always come to a complete stop', 'Speed up to join traffic', 'Turn around'], 'YIELD: slow down, check, and let pedestrians and cross traffic go first. You stop only when it is necessary.', 'yield'],
  ['s04', 'signs', 'What does this sign mean?', ['Do not enter', 'Stop', 'Yield', 'No U-turn'], 'DO NOT ENTER stands at the start of one-way streets and ramps. Do not drive in.', 'dne'],
  ['s05', 'signs', 'You turn onto a ramp and see this sign farther down. What does it tell you?', ['You are driving against traffic', 'The ramp is closed for repairs', 'Trucks may not use the ramp', 'A toll booth is ahead'], 'WRONG WAY signs stand farther down a one-way street or ramp, to catch you if you turned in by mistake.', 'wrongway'],
  ['s06', 'signs', 'What does this sign mean?', ['Traffic may move only in the direction of the arrow', 'You must turn right at the next corner', 'The right lane ends', 'Detour to the right'], 'ONE WAY: all traffic on that street goes the way the arrow points.', 'oneway'],
  ['s07', 'signs', 'What does this sign mean?', ['No left turn', 'No right turn', 'No U-turn', 'No turning at all'], 'A red circle with a slash over a symbol means that action is prohibited. Here: turning left.', 'noleft'],
  ['s08', 'signs', 'What does this sign mean?', ['No right turn', 'No left turn', 'No U-turn', 'Right lane closed'], 'The slash is over an arrow turning right: do not turn right here.', 'noright'],
  ['s09', 'signs', 'What does this sign mean?', ['No U-turn', 'No left turn', 'No right turn', 'Dead end'], 'Do not make a complete turn to go back the way you came.', 'nouturn'],
  ['s10', 'signs', 'This sign is posted at a traffic light. What does it mean?', ['You may not turn during the red light; wait for green', 'You may turn on red after a full stop', 'The light is out of order', 'Only left turns are banned'], 'Without this sign a right turn on red is allowed after stopping. With it, you wait for green.', 'notor'],
  ['s11', 'signs', 'What does this sign tell you?', ['Keep to the right of the island or divider', 'Right turns only', 'The road curves right', 'Pass only on the right'], 'KEEP RIGHT signs direct you to the right of a traffic island or divider.', 'keepright'],
  ['s12', 'signs', 'What does the number on this sign show?', ['The maximum safe speed under ideal road and weather conditions', 'The minimum legal speed', 'The exact speed you must drive', 'The maximum safe speed under all conditions'], 'Posted limits are for ideal conditions. In rain, fog or traffic you must drive slower.', 'speed'],
  ['s13', 'signs', 'This sign stands right at railroad tracks. How should you treat it?', ['Like a YIELD sign: slow down and be ready to stop for a train', 'Like a STOP sign: always stop', 'Like a green light: keep your speed', 'It is only for trucks and buses'], 'The crossbuck marks the crossing itself. Treat it as a YIELD sign.', 'crossbuck'],
  ['s14', 'signs', 'What does this sign mean?', ['A no-passing zone begins', 'The road narrows to one lane', 'Slow-moving vehicles ahead', 'Merge to the right'], 'The pennant marks the start of a no-passing zone. It stands on the left side of the road.', 'nopass'],
  ['s15', 'signs', 'Which sign is the only one shaped like a pennant (a long sideways triangle)?', ['NO PASSING ZONE', 'YIELD', 'SCHOOL', 'MERGING TRAFFIC'], 'No other sign has the pennant shape.'],
  ['s16', 'signs', 'What does this sign mean?', ['A railroad crossing is ahead', 'A rest area is ahead', 'A roundabout is ahead', 'The road is closed ahead'], 'The round yellow sign is the advance warning. Start looking and listening for a train.', 'rr'],
  ['s17', 'signs', 'What does this sign mean?', ['You are near a school zone: slow down and watch for children', 'A playground is closed', 'Pedestrians may not cross here', 'A hospital is ahead'], 'SCHOOL signs are yellow or fluorescent yellow-green. Slow down and be ready to stop.', 'school'],
  ['s18', 'signs', 'Which sign is the only one with five sides?', ['SCHOOL', 'STOP', 'YIELD', 'NO PASSING ZONE'], 'The pentagon is used only for the school sign.'],
  ['s19', 'signs', 'What does this sign warn you about?', ['Pedestrians may be crossing ahead', 'A school bus stop', 'A hiking trail', 'A flagger ahead'], 'Be prepared to slow down or stop for people crossing.', 'ped'],
  ['s20', 'signs', 'What is the meaning of this sign?', ['There is a traffic signal ahead', 'The traffic signal ahead is broken', 'The traffic signal ahead is red', 'The traffic signal ahead is green'], 'It warns of a signal you may not be able to see yet, for example behind a curve or hill.', 'signal'],
  ['s21', 'signs', 'What does this sign tell you?', ['A STOP sign is ahead: slow down and get ready to stop', 'Stop right here', 'The road ends ahead', 'A four-way stop is closed'], 'You may not see the STOP sign yet, or a line of stopped cars may be waiting at it.', 'stopahead'],
  ['s22', 'signs', 'This sign is on a major road. Who must yield?', ['The traffic entering from the right', 'The traffic already on the major road', 'Whoever is driving slower', 'Nobody has to yield'], 'MERGING TRAFFIC: entering traffic must yield to traffic already on the major roadway. Still be ready to make room.', 'merge'],
  ['s23', 'signs', 'This sign is used to warn drivers about:', ['A lane that ends: traffic must merge left', 'A road that curves ahead', 'An intersection ahead', 'Road construction'], 'One lane of a multi-lane road ends. Traffic in the right lane must merge left.', 'laneends'],
  ['s24', 'signs', 'What does this sign mean?', ['A divided highway begins', 'A divided highway ends', 'A one-way street begins', 'Two lanes merge'], 'A median is about to separate the two directions. Keep to the right of it.', 'divbegins'],
  ['s25', 'signs', 'What does this sign mean?', ['The divided highway ends', 'The divided highway begins', 'A one-way street ends', 'Passing is allowed'], 'After it you are on a road with two-way traffic and no divider. Watch for oncoming traffic.', 'divends'],
  ['s26', 'signs', 'What does this sign mark?', ['A road with two-way traffic', 'A divided highway', 'A passing zone', 'A one-way street'], 'The one-way road ends. Stay in your lane, to the right of the centre line.', 'twoway'],
  ['s27', 'signs', 'This sign shows one type of:', ['Intersection', 'Road curve', 'Lane change', 'Railroad crossing'], 'Intersection signs show in advance how the roads join. Here another road crosses yours.', 'crossroad'],
  ['s28', 'signs', 'What does this sign warn you about?', ['A road that enters from the right', 'A sharp right turn', 'A lane that ends on the right', 'An exit ramp'], 'A side road joins yours. A driver may pull out, so approach with extra caution.', 'sideroad'],
  ['s29', 'signs', 'What must you do after this sign?', ['Turn left or right, because your road ends', 'Go straight on', 'Make a U-turn', 'Stop and wait for a signal'], 'At a T-intersection the road you are on does not continue straight.', 'tee'],
  ['s30', 'signs', 'This sign is used to warn drivers about:', ['A curve in the road ahead', 'An upcoming intersection', 'A change in traffic lanes', 'Road construction'], 'The road curves to the right. Slow down before you reach the curve.', 'curve'],
  ['s31', 'signs', 'What does this sign tell you?', ['There is a series of curves ahead', 'The road is slippery when wet', 'No turns are allowed', 'The road narrows'], 'WINDING ROAD: three or more curves in a row.', 'winding'],
  ['s32', 'signs', 'When you see this black and yellow sign, it means:', ['Slow down: the road ahead changes direction at an extreme angle', 'The road to the right is one-way', 'Detour to the right for road work', 'A cross road is ahead on your right'], 'Slow down as much as you would to make a turn at an intersection.', 'bigarrow'],
  ['s33', 'signs', 'What does this sign tell you?', ['The road bends sharply in the direction it points', 'An object is on the roadway', 'Traffic is merging from the left', 'A merge point is ahead'], 'Chevron signs are placed through a sharp curve. The road bends the way the chevron points.', 'chevron'],
  ['s34', 'signs', 'What does this sign mean?', ['Slippery when wet', 'Winding road', 'Car wash ahead', 'Drunk drivers ahead'], 'In wet weather slow down, leave more room, and do not brake or accelerate quickly.', 'slippery'],
  ['s35', 'signs', 'This sign indicates that:', ['There is a steep hill ahead', 'No trucks are allowed on the hill', 'A logging road is ahead', 'Trucks are parked on the hill'], 'Slow down and be ready to shift to a lower gear to control your speed and save your brakes.', 'hill'],
  ['s36', 'signs', 'What should concern you most when you see this sign?', ['Losing control if you drift onto the shoulder, because of the drop-off', 'Damaging a tire on the shoulder', 'Hydroplaning on the shoulder', 'Your headlights being out of alignment'], 'If a wheel drops off the pavement, do not brake hard or steer sharply to get back.', 'lowshoulder'],
  ['s37', 'signs', 'What does this sign tell you?', ['There is road work ahead: slow down', 'The road is closed', 'A detour begins here', 'Workers have finished for the day'], 'Work zone signs are orange with black letters.', 'work'],
  ['s38', 'signs', 'What does this sign mean?', ['A flagger is ahead, controlling traffic', 'Pedestrians ahead', 'School crossing ahead', 'End of the construction zone'], 'Flaggers use STOP and SLOW paddles or a red flag. Their directions override other traffic controls.', 'flagger'],
  ['s39', 'signs', 'What does this sign mean?', ['Workers are on or very close to the road ahead', 'Children are at play ahead', 'A pedestrian crosswalk is ahead', 'A community group is picking up litter'], 'Take special care when you drive through the area.', 'workers'],
  ['s40', 'signs', 'You see this sign above your lane on a highway. What does it mean?', ['You must exit the highway if you stay in this lane', 'You may not exit from this lane', 'This lane continues through the interchange', 'This lane is for trucks only'], 'A yellow EXIT ONLY panel means the lane becomes the ramp. Change lanes if you do not want to exit.', 'exitonly'],
  ['s41', 'signs', 'What kind of sign is this?', ['A service sign', 'A warning sign', 'A regulatory sign', 'A work zone sign'], 'Blue signs with white letters or symbols show services at the next exit: hospitals, gas, food.', 'hospital'],
  ['s42', 'signs', 'This emblem is on the back of a vehicle. What does it tell you?', ['The vehicle travels at slower speeds than normal traffic', 'The vehicle carries radioactive material', 'The vehicle makes wide turns', 'The vehicle makes frequent stops'], 'The orange triangle is on farm tractors and horse-drawn vehicles built to go 25 mph or less.', 'slow'],
  ['s43', 'signs', 'A yellow and black diamond-shaped sign:', ['Warns you about conditions on or near the road', 'Tells you about traffic laws', 'Directs you to cities and towns', 'Tells you about road construction'], 'Warning signs are diamonds with black symbols on yellow, posted before the hazard.'],
  ['s44', 'signs', 'Highway and expressway guide signs are:', ['Green with white letters', 'Orange with black letters', 'Yellow with black letters', 'Red with white letters'], 'Green guide signs show exits, routes, cities and distances.'],
  ['s45', 'signs', 'What colour are work zone signs?', ['Orange with black letters', 'Yellow with black letters', 'Green with white letters', 'Blue with white letters'], 'They are diamond-shaped like warning signs, but orange.'],
  ['s46', 'signs', 'What do regulatory signs tell you?', ['What you must do or must not do, by law', 'What hazards are ahead', 'How far the next city is', 'Where services are'], 'They are usually black and white rectangles or squares. Some are red and white, like STOP.'],
  ['s47', 'signs', 'At a four-way stop, which vehicle should go first?', ['The first vehicle to reach the intersection', 'The vehicle on the widest road', 'The vehicle going straight', 'The largest vehicle'], 'All four directions stop. The first to arrive moves first.'],
  ['s48', 'signs', 'Two vehicles reach a four-way stop at the same time, from different roads. Who yields?', ['The driver on the left yields to the driver on the right', 'The driver on the right yields to the driver on the left', 'The driver going straight yields', 'The faster driver yields'], 'Same time: the one on the left waits.'],
  ['s49', 'signs', 'You stop behind the white stop line at a STOP sign, but you cannot see cross traffic. What should you do?', ['Pull forward slowly, check for traffic and pedestrians, and go when clear', 'Wait 5 seconds, then go', 'Sound your horn, then go', 'Open the window, listen, then go'], 'First stop at the line and yield to pedestrians. Then creep forward until you can see.'],
  ['s50', 'signs', 'You are in a lane marked with a turn arrow and the word ONLY, but you wanted to go straight. What must you do?', ['Make the turn', 'Go straight if it is clear', 'Stop and wait for a gap', 'Back up and change lanes'], 'You must go the way the arrow points, even if you are in the lane by mistake.'],
  ['s51', 'signs', 'A small yellow sign with a speed, such as 25 mph, is posted under a curve warning sign. What is it?', ['The highest speed you should travel through the curve', 'The legal speed limit for the whole road', 'The minimum speed for the curve', 'A speed for trucks only'], 'Advisory speed signs go with warning signs and give the highest speed you should travel there.'],
  ['s52', 'signs', 'When must you turn on your headlights in a posted work zone?', ['Always, whatever the time of day', 'Only at night', 'Only when workers are present', 'Only when it rains'], 'It is the law for all posted work zones. Stopped for a violation there without headlights: $25 more.'],
  ['s53', 'signs', 'An arrow panel in a work zone shows a flashing bar or four corner lights instead of an arrow. It means:', ['Drive with caution', 'Change lanes immediately', 'The bulbs are burned out', 'Tune your radio to traffic news'], 'The caution pattern means there is a work area ahead next to your lane.'],
  ['s54', 'signs', 'Exit numbers match the mile markers. How far is it from Exit 95 to Exit 20?', ['75 miles', '95 miles', '20 miles', '115 miles'], 'Subtract one exit number from the other.'],
  ['s55', 'signs', 'An interstate has a one- or two-digit even number, like I-80. Which way does it generally run?', ['East and west', 'North and south', 'Around a city', 'Into a city centre'], 'Even numbers run east-west, odd numbers north-south.'],
  ['s56', 'signs', 'An ADDED LANE sign is posted where two roads meet. What does it mean?', ['Merging is not needed: entering traffic gets its own new lane', 'Your lane ends ahead', 'You must yield to entering traffic', 'The right lane is for buses only'], 'Unlike MERGING TRAFFIC, a new lane is added for the entering vehicles.'],
  ['s57', 'signs', 'A marker with diagonal stripes stands beside an object near the road. Which way do the stripes point?', ['Down toward the side you should pass on', 'Up toward the side you should pass on', 'Toward the nearest exit', 'They have no meaning'], 'Object markers warn of bridge ends, guiderails and drop-offs. Follow the downward slope of the stripes.'],

  /* ---------- signals and pavement markings ---------- */
  ['g01', 'signals', 'From top to bottom, what is the order of the lights on a traffic signal?', ['Red, yellow, green', 'Red, green, yellow', 'Green, yellow, red', 'Green, red, yellow'], 'Vertical signals always have red on top and green at the bottom.'],
  ['g02', 'signals', 'On a traffic signal arranged in a horizontal line, where is the red light?', ['On the left', 'On the right', 'In the middle', 'It changes'], 'Horizontal: red on the left, green on the right.'],
  ['g03', 'signals', 'You face a steady red light and there is no stop line and no crosswalk. Where do you stop?', ['Before entering the intersection', 'In the middle of the intersection', 'Past the intersection', 'Anywhere, as long as you stop'], 'With lines, stop before the stop line or crosswalk. Without, before the intersection.'],
  ['g04', 'signals', 'You may turn right on red if you:', ['Stop first and check for traffic and pedestrians', 'Slow down first', 'Are in the left lane', 'See a red arrow pointing right'], 'Stop, yield to pedestrians and traffic, then turn, unless a NO TURN ON RED sign is posted.'],
  ['g05', 'signals', 'You may turn left at a red light if:', ['You are turning from a one-way street onto another one-way street', 'You are turning from a two-way street onto a one-way street', 'No traffic is coming from the opposite direction', 'The car in front of you turns left'], 'Only one-way to one-way, from the left lane, after a full stop, and with no sign forbidding it.'],
  ['g06', 'signals', 'A steady yellow light at an intersection means:', ['Slow down and prepare to stop', 'Go', 'Yield to other cars', 'Stop, whatever happens'], 'It tells you a steady red light will soon appear.'],
  ['g07', 'signals', 'You may continue carefully through a yellow light if:', ['You are already within the intersection', 'You are turning right', 'No pedestrians are crossing', 'An emergency vehicle is crossing'], 'Also if you cannot stop safely before the intersection. Otherwise prepare to stop.'],
  ['g08', 'signals', 'A steady green light at an intersection means that you:', ['May drive through the intersection if the road is clear', 'Must stop and check before going', 'Must slow down and prepare to stop', 'May not turn right'], 'When turning on green you must still yield to vehicles and pedestrians in the intersection.'],
  ['g09', 'signals', 'You turn left on a steady green arrow. Why is that turn called "protected"?', ['Oncoming traffic is stopped by a red light', 'You may turn at any speed', 'Police are watching the intersection', 'Pedestrians must run'], 'During the green arrow the opposing traffic has red.'],
  ['g10', 'signals', 'A green arrow turns into a plain green light. You:', ['May still turn, but must yield to oncoming traffic', 'May no longer turn', 'Still have the right-of-way to turn', 'Must stop until the arrow returns'], 'The protection is over. Yield to pedestrians and oncoming traffic first.'],
  ['g11', 'signals', 'What does a steady red arrow mean?', ['Stop: you may not go in the direction of the arrow', 'Turn that way with caution', 'Yield, then turn', 'The lane is closed'], 'Wait for a green arrow or a flashing yellow arrow. The same turns on red that a red light allows are allowed.'],
  ['g12', 'signals', 'A flashing yellow arrow means:', ['You may turn with caution after yielding to oncoming traffic and pedestrians', 'Your turn is protected', 'Stop and wait for green', 'The signal is broken'], 'Oncoming traffic has a green light, so this turn is NOT protected.'],
  ['g13', 'signals', 'You must stop when you see a:', ['Flashing red light', 'Flashing yellow light', 'Steady yellow light', 'Yellow arrow'], 'A flashing red light means the same as a STOP sign.'],
  ['g14', 'signals', 'A flashing yellow light means that you should:', ['Slow down and proceed with care', 'Stop and go when the way is clear', 'Stop and wait for green', 'Keep your speed if the way is clear'], 'Flashing yellow means caution.'],
  ['g15', 'signals', 'A traffic light is broken or not working. You should:', ['Continue as if it were a four-way stop sign', 'Continue as you normally would', 'Stop and wait for it to be repaired', 'Stop and wait for a police officer'], 'Treat a dead signal as a four-way STOP.'],
  ['g16', 'signals', 'A signal at the end of a highway entrance ramp turns green. What is true?', ['You may go, but you must still find a safe gap in traffic', 'Highway traffic must stop for you', 'Three cars may go on each green', 'You may pass the car ahead on the ramp'], 'Ramp meters let one car go per green on a single-lane ramp. Green does not protect your entrance.'],
  ['g17', 'signals', 'A steady green arrow pointing down is lit above your lane. It means:', ['You may use this lane', 'You must merge into this lane', 'No traffic is allowed in this lane', 'You have the right-of-way'], 'Lane signals are used at toll booths, bridges, tunnels and on reversible lanes.'],
  ['g18', 'signals', 'A steady yellow X is lit above your lane. What should you do?', ['Get ready to leave the lane safely', 'Stop immediately', 'Speed up', 'Use the lane for left turns only'], 'The direction of that lane is about to be reversed.'],
  ['g19', 'signals', 'A steady red X is lit above a lane. It means:', ['You are not allowed to use that lane', 'The lane is for buses', 'Stop and wait in that lane', 'The lane ends in one mile'], 'Stay out of a lane under a red X.'],
  ['g20', 'signals', 'A pedestrian is in the street when the DON’T WALK signal starts flashing. The pedestrian should:', ['Finish crossing', 'Go back to the curb they left', 'Stop and stand still', 'Wait in the middle for the next WALK'], 'Flashing: finish if you started, do not start if you have not left the curb.'],
  ['g21', 'signals', 'When driving near a blind pedestrian who carries a white cane or uses a guide dog, you should:', ['Slow down and be prepared to stop', 'Take the right-of-way', 'Proceed normally', 'Drive away quickly'], 'Always yield the right-of-way to a blind pedestrian.'],
  ['g22', 'signals', 'What is the speed limit when the yellow lights on a school zone sign are flashing?', ['15 mph', '20 mph', '25 mph', '35 mph'], 'It also applies during the time periods shown on the sign.'],
  ['g23', 'signals', 'What happens if you exceed the speed limit in a school zone?', ['Three points on your record and a fine', 'A warning only', 'One point and no fine', 'A one-year suspension'], 'School zone speeding costs three points plus a fine.'],
  ['g24', 'signals', 'Flashing red lights at a railroad crossing mean:', ['Stop, and do not proceed until the signals are finished', 'Slow down and proceed if clear', 'Proceed with caution', 'You have the right-of-way'], 'Also stop for a lowered gate, a flagger, or a train’s horn.'],
  ['g25', 'signals', 'You may drive around the gates at a railroad crossing:', ['Never', 'When the train has passed', 'When the lights stop flashing', 'When other drivers do'], 'Failing to obey a crossing gate brings a 30-day licence suspension.'],
  ['g26', 'signals', 'If there are no signals at a railroad crossing, you should:', ['Slow down and prepare to stop if you see or hear a train', 'Cross as quickly as possible', 'Cross at normal speed', 'Always stop and turn off the engine'], 'Most crossings have only a warning sign and a crossbuck. Look and listen every time.'],
  ['g27', 'signals', 'Traffic is backed up from a red light, and a railroad track is between you and the last car. Where do you stop?', ['Before the tracks, where your car is entirely clear of them', 'On the tracks, close to the car ahead', 'Half across the tracks', 'It does not matter if no train is in sight'], 'Never stop on a track, whether or not a train seems to be coming.'],
  ['g28', 'signals', 'Lanes of traffic moving in opposite directions are divided by ___ lines.', ['Yellow', 'White', 'Red', 'Black'], 'Yellow separates opposite directions.'],
  ['g29', 'signals', 'Lanes of traffic moving in the same direction are divided by ___ lines.', ['White', 'Yellow', 'Red', 'Orange'], 'White separates lanes going the same way.'],
  ['g30', 'signals', 'The right edge of the road is marked by a:', ['Solid white line', 'Solid yellow line', 'Broken white line', 'Broken yellow line'], 'The left edge of a divided highway or one-way road is a solid yellow line.'],
  ['g31', 'signals', 'You may pass if the line dividing two lanes going your way is a:', ['Broken white line', 'Solid white line', 'Solid yellow line', 'Double solid yellow line'], 'Broken lines can be crossed. Be sure the passing lane is clear.'],
  ['g32', 'signals', 'You may not pass another car on either side of a:', ['Double solid yellow centre line', 'Single broken yellow centre line', 'Solid and broken yellow centre line', 'Broken white line'], 'Double solid yellow: no passing for traffic in either direction.'],
  ['g33', 'signals', 'The centre line is a solid yellow line next to a broken yellow line. When may you pass?', ['When the broken line is on your side and it is safe', 'When the solid line is on your side', 'Never', 'Only at night'], 'A solid line on your side means no passing for you.'],
  ['g34', 'signals', 'You may cross solid yellow lines:', ['When making turns', 'To pass traffic going your way', 'During daylight only', 'At any time'], 'Solid lines cannot be crossed, except when making a turn.'],
  ['g35', 'signals', 'A centre lane is marked on both sides with a solid yellow line and a broken yellow line. It is used for:', ['Left turns only', 'Passing only', 'Regular travel', 'Emergency vehicles only'], 'Drivers from either direction use it to turn left. Never use it to pass.'],
  ['g36', 'signals', 'When making a right turn on a green light, you must:', ['Yield to pedestrians', 'Stop and look for oncoming traffic', 'Keep your normal driving speed', 'Speed up'], 'Green lets you go, but turning drivers yield to pedestrians crossing with the light.'],
  ['g37', 'signals', 'A steady yellow light means that a ___ light will soon appear.', ['Steady red', 'Steady green', 'Flashing red', 'Flashing yellow'], 'Yellow comes between green and red.'],
  ['g38', 'signals', 'White triangles are painted across your lane ahead. What do they mean?', ['You must yield to approaching traffic', 'A school zone begins', 'Passing is allowed', 'A bike lane ends'], 'Painted words and symbols repeat what the signs say: STOP AHEAD, YIELD, SCHOOL, R X R, ONLY.'],

  /* ---------- safety first, space, speed and night ---------- */
  ['p01', 'space', 'The most effective thing you can do to reduce your risk of being injured or killed in a crash is:', ['Wear your seat belt', 'Drive only on weekdays', 'Stay in the right lane', 'Drive only in the afternoon'], 'Fasten the lap and shoulder belt on every trip.'],
  ['p02', 'space', 'When should you adjust your mirrors?', ['After you adjust your seat', 'Before you adjust your seat', 'While driving slowly', 'Only at night'], 'The mirror settings depend on where you sit.'],
  ['p03', 'space', 'What does the law say about hanging things from the rearview mirror?', ['Nothing may hang from it while the vehicle is moving', 'Only air fresheners are allowed', 'Anything smaller than a hand is allowed', 'It is allowed in daylight'], 'Tags and placards may hang there only while the vehicle is parked.'],
  ['p04', 'space', 'How high should your head restraint be?', ['Its top at least as high as the top of your ears', 'Level with your shoulders', 'As low as it goes', 'Removed, for a better view'], 'A properly set head restraint reduces neck injuries.'],
  ['p05', 'space', 'The "four-second rule" refers to how you should:', ['Follow another car', 'Turn at stop signs', 'Yield to other cars', 'Cross an intersection'], 'It is the safe following distance on a dry road.'],
  ['p06', 'space', 'At highway speeds on a dry road, a safe following distance is at least:', ['4 seconds', '2 seconds', '3 seconds', '2 car lengths'], 'Pick a marker, and count the seconds between the car ahead passing it and you reaching it.'],
  ['p07', 'space', 'It is best to keep a space cushion:', ['On all sides of your vehicle', 'Only in front', 'Only behind', 'Only on the left and right'], 'Space ahead, behind and on both sides gives you escape paths.'],
  ['p08', 'space', 'Why is a space cushion important?', ['It gives you time to react to situations', 'It keeps other drivers alert', 'It keeps traffic moving faster', 'It prevents distractions'], 'If another driver makes a mistake, space is time.'],
  ['p09', 'space', 'Allow a larger space cushion than usual when stopping:', ['On an uphill', 'At a stop sign', 'At a toll plaza', 'At an intersection'], 'The vehicle ahead may roll back when traffic starts to move.'],
  ['p10', 'space', 'You have less than 8 feet of space on both sides of your car. What should you do?', ['Increase your following distance', 'Drive on the shoulder', 'Speed up to get clear', 'Turn on your high beams'], 'With no escape path to the side, you need more room in front.'],
  ['p11', 'space', 'Parked cars are on your right and oncoming cars on your left. What is the best thing to do?', ['Slow down and steer a middle course between them', 'Drive close to the parked cars', 'Drive close to the centre line', 'Stop until the road is empty'], 'The manual calls this "splitting the difference".'],
  ['p12', 'space', 'Someone is tailgating you and there is a right lane. What should you do?', ['Move over to the right lane', 'Brake hard to warn them', 'Speed up', 'Stare at them in the mirror'], 'No right lane: when the road ahead is clear, tap the brakes gently and slow down so they go around.'],
  ['p13', 'space', 'Your blind spot is the area of the road:', ['You cannot see without moving your head', 'Directly behind your vehicle', 'You see in your rearview mirror', 'You see in your side mirror'], 'Mirrors and sensors do not cover it. Turn your head.'],
  ['p14', 'space', 'Before changing lanes on a multi-lane highway you should:', ['Check your mirrors and blind spots', 'Sound your horn', 'Turn on your headlights', 'Reduce your speed'], 'Signal, check the mirrors, then look over your shoulder.'],
  ['p15', 'space', 'How far ahead should you be looking for problem situations?', ['12 to 15 seconds', '2 to 4 seconds', '5 to 6 seconds', '30 to 40 seconds'], 'That is about one block in the city, or a quarter of a mile at highway speed.'],
  ['p16', 'space', 'To prepare for anything coming up in the road ahead, you should:', ['Continually scan the entire road and roadsides', 'Stare straight ahead at all times', 'Rest your left foot on the brake', 'Focus on the middle of the road'], 'Looking far ahead does not mean staring at one spot.'],
  ['p17', 'space', 'Before backing up, you should:', ['Turn your head and look through the rear window', 'Rely on your mirrors', 'Flash your lights', 'Open your door to look'], 'Also check behind the car before you get in. Children are hard to see from the seat.'],
  ['p18', 'space', 'What is the maximum speed limit in Pennsylvania?', ['70 mph', '55 mph', '60 mph', '75 mph'], 'The current manual says 70. An older PennDOT sample question offers 65 as its highest choice.'],
  ['p19', 'space', 'Drive below the posted speed limit when:', ['Anything makes conditions less than perfect', 'Others drive below the limit', 'You enter a highway', 'You are on a four-lane road'], 'Wet roads, poor visibility, heavy traffic: all mean slower.'],
  ['p20', 'space', 'Which of the following is true about the speed at which you travel?', ['The safe speed to drive depends on many conditions', 'The speed limit is always a safe speed', 'Driving slowly is always safer', 'Accelerating is always dangerous'], 'Consider the limit, the road, visibility and the flow of traffic.'],
  ['p21', 'space', 'You are driving within the speed limit on a wet, foggy road. Can you get a ticket?', ['Yes, for driving too fast for conditions', 'No, the limit is all that counts', 'Only on interstates', 'Only at night'], '"Driving too fast for conditions" is also the No. 1 reason 16- and 17-year-olds crash.'],
  ['p22', 'space', 'Compared to driving during the day, driving at night is:', ['More dangerous', 'Less dangerous', 'No more or less dangerous', 'Easier on your eyes'], 'Traffic death rates are three to four times higher at night.'],
  ['p23', 'space', 'At night, it is hardest to see:', ['Pedestrians', 'Road signs', 'Other motorists', 'Street lights'], 'Compared with signs and roadside objects, pedestrians are the hardest to see.'],
  ['p24', 'space', 'You must use your headlights when other vehicles are not visible from ___ feet away.', ['1,000', '500', '300', '2,000'], 'Also between sunset and sunrise, in bad weather, in work zones, and when the wipers are on.'],
  ['p25', 'space', 'It is raining and your wipers are on. What does Pennsylvania law require?', ['Headlights on', 'Hazard flashers on', 'Daytime running lights only', 'Nothing extra'], 'Daytime running lights are not enough: your tail lights must be lit too.'],
  ['p26', 'space', 'When must you switch from high beams to low beams?', ['Within 500 feet of an oncoming vehicle and 300 feet behind a vehicle', 'Within 100 feet of any vehicle', 'Only in the city', 'Within 1,000 feet of an oncoming vehicle'], '500 feet for oncoming traffic, 300 feet when following.'],
  ['p27', 'space', 'If a vehicle using high beams comes toward you, you should:', ['Flash your high beams', 'Turn on your high beams and leave them on', 'Turn off your headlights', 'Sound your horn'], 'Flash them quickly a few times. Do not keep them on to punish the other driver.'],
  ['p28', 'space', 'An oncoming driver does not dim their high beams. Where should you look?', ['Toward the right side of the road', 'Toward the left side of the road', 'At the centre line', 'Straight at the headlights'], 'It keeps you from being blinded and lets you hold your course.'],
  ['p29', 'space', 'Low beams light the road for only about 250 feet. On a dark road at night, you should not drive faster than:', ['45 mph', '55 mph', '65 mph', '35 mph'], 'Driving faster means you cannot stop within what your headlights show.'],
  ['p30', 'space', 'Roads become very slippery:', ['For the first 10 to 15 minutes of a rainstorm', 'When it has rained for an hour or more', 'The day after it rains', 'Right after the rain has stopped'], 'The rain brings oil in the asphalt to the surface.'],
  ['p31', 'space', 'Roads freeze more quickly when they are:', ['Shaded', 'In the sun', 'Flat', 'Curvy'], 'Shaded sections freeze first and dry last.'],
  ['p32', 'space', 'Hydroplaning is usually caused by:', ['Excessive speed', 'Sudden stops', 'Sudden turns', 'Excessive stops'], 'It can start at 35 mph in water only 1/10 of an inch deep. Driving slower prevents it.'],
  ['p33', 'space', 'Your car starts to hydroplane. What should you do?', ['Slowly take your foot off the gas and keep both hands on the wheel', 'Brake hard', 'Turn the wheel sharply', 'Accelerate out of it'], 'Braking hard or turning suddenly will make the car skid.'],
  ['p34', 'space', 'When driving on wet roads, you should:', ['Drive 5 to 10 mph below the speed limit', 'Drive the speed limit', 'Drive slightly above the limit', 'Stay close to the vehicle ahead'], 'On packed snow, cut your speed in half. On ice, slow to a crawl.'],
  ['p35', 'space', 'When driving on wet roads, your following distance should be:', ['5 or 6 seconds', '2 seconds', '4 seconds, as always', 'Whatever feels right'], 'It takes longer to stop on a wet road.'],
  ['p36', 'space', 'Which of the following is true about driving on a wet roadway?', ['As you drive faster, your tires become less effective', 'Water does not affect cars with good tires', 'Deeper water is less dangerous', 'Slowing down makes the road more slippery'], 'The faster you go, the less water the tires can wipe away.'],
  ['p37', 'space', 'Should you use cruise control on a slippery road?', ['No', 'Yes, it keeps your speed steady', 'Only in snow', 'Only below 45 mph'], 'It keeps applying power when the wheels spin, and you lose control.'],
  ['p38', 'space', 'The road looks wet, but no spray comes from the tires of other vehicles. What may be present?', ['Black ice', 'Fresh oil', 'A flooded road', 'Loose gravel'], 'Black ice is a thin layer of ice on a road that looks clear.'],
  ['p39', 'space', 'When driving in fog, you should use your:', ['Low beam headlights', 'High beam headlights', 'Parking lights', 'Hazard flashers'], 'High beams bounce off the fog back into your eyes.'],
  ['p40', 'space', 'When driving in traffic, it is safest to:', ['Drive with the flow of traffic', 'Drive faster than the flow', 'Drive slower than the flow', 'Keep changing your speed'], 'Within the posted limit. Crashes happen when drivers go much faster or slower than the rest.'],
  ['p41', 'space', 'A bicyclist is on your right and a car is coming toward you on the left. You should:', ['Let the car pass, and then pass the bike', 'Split the difference between them', 'Pass the bike quickly', 'Pull onto the shoulder'], 'Handle one hazard at a time, then pass the cyclist with at least 4 feet of room.'],
  ['p42', 'space', 'You are driving at 25 mph. How far before a turn must you signal?', ['At least 100 feet', 'At least 300 feet', 'At least 50 feet', 'At least 500 feet'], 'Under 35 mph: 100 feet. At 35 mph or more: 300 feet.'],
  ['p43', 'space', 'You are driving at 45 mph. How far before a turn must you signal?', ['At least 300 feet', 'At least 100 feet', 'At least 200 feet', 'At least 1,000 feet'], 'At 35 mph or more the law asks for 300 feet.'],
  ['p44', 'space', 'If you need to slow down or stop when other drivers may not expect it, you should:', ['Quickly tap your brake pedal a few times', 'Use your parking brake', 'Sound your horn', 'Look over your shoulder'], 'Three or four quick taps flash your brake lights as a warning.'],
  ['p45', 'space', 'When travelling below 40 mph on a limited access highway, you should:', ['Use your four-way flashers', 'Use your high beams', 'Drive on the shoulder', 'Sound your horn'], 'The flashers warn the faster drivers behind you.'],
  ['p46', 'space', 'A driver holds the left arm straight out of the window. The driver is:', ['Turning left', 'Turning right', 'Slowing or stopping', 'Waving you past'], 'Hand signals: straight out = left, bent up = right, bent down = slow or stop.'],
  ['p47', 'space', 'A driver holds the left arm out of the window, bent upward. The driver is:', ['Turning right', 'Turning left', 'Stopping', 'Backing up'], 'Arm up means a right turn.'],
  ['p48', 'space', 'A driver holds the left arm out of the window, pointing down. The driver is:', ['Slowing or stopping', 'Turning left', 'Turning right', 'Opening the door'], 'Arm down means slowing or stopping.'],
  ['p49', 'space', 'If your turn signals fail, you should use ___ to show you are turning.', ['Hand signals', 'Your horn', 'Your headlights', 'Your emergency flashers'], 'Hand signals replace broken turn signals.'],
  ['p50', 'space', 'You should honk your horn when you:', ['See a child who is about to run into the street', 'Are passing a bicyclist', 'Are parallel parking', 'Are travelling through an intersection'], 'Also when another vehicle is about to hit you, or when you have lost control of your car.'],
  ['p51', 'space', 'Your brake lights tell other drivers that you:', ['Are slowing down or stopping', 'Are making a turn', 'Are changing lanes', 'Have your parking brake on'], 'Signal your intentions: brake lights for slowing, turn signals for turning.'],
  ['p52', 'space', 'To help avoid crashes, you should:', ['Communicate with other drivers on the road', 'Ignore other drivers', 'Drive only on back roads', 'Avoid rush hour'], 'Crashes often happen because one driver does something another does not expect.'],
  ['p53', 'space', 'What can you do to avoid emergency ("panic") stops in traffic?', ['Look ahead and keep a safe following distance', 'Honk to make others aware of you', 'Drive in the right lane only', 'Drive slower than the flow of traffic'], 'Seeing a problem early and having room is what saves you.'],
  ['p54', 'space', 'Your ability to stop is affected by:', ['The condition of the road', 'Signal lights', 'The time of day', 'Other cars on the road'], 'Slow down when the road is wet, icy or unpaved.'],

  /* ---------- turns, passing, intersections and parking ---------- */
  ['t01', 'turns', 'When you plan to make a turn, when should you switch on your turn signal?', ['3 to 4 seconds before you reach the intersection', 'Just as the front of your car reaches the intersection', 'Two car lengths before the intersection', 'Only if other drivers are following you'], 'In distance, the law says at least 100 feet under 35 mph and 300 feet at 35 mph or more.'],
  ['t02', 'turns', 'When making a turn, you must ___ your speed.', ['Reduce', 'Increase', 'Maintain', 'Vary'], 'Slow enough to keep control and stay in your lane through the turn.'],
  ['t03', 'turns', 'On two-lane, two-way streets or highways, you should start left turns:', ['Close to the centre line', 'Close to the outside line', 'In the centre of the lane', 'Anywhere in the lane'], 'And start right turns as close to the right edge as possible.'],
  ['t04', 'turns', 'To turn left on multi-lane streets and highways, you should start from:', ['The left lane', 'The right lane', 'The middle of the intersection', 'Any lane'], 'Left turns from the left lane, right turns from the right lane.'],
  ['t05', 'turns', 'You turn onto a road with several lanes going your way. Which lane do you turn into?', ['The closest lane going in your direction', 'The farthest lane', 'Any lane that is empty', 'The centre turn lane'], 'If you want another lane, change after you have completed the turn.'],
  ['t06', 'turns', 'Before making a U-turn, how far away must other drivers be?', ['At least 500 feet, and able to see you clearly', 'At least 100 feet', 'At least 50 feet', 'Distance does not matter'], 'A U-turn is allowed only if it does not endanger other traffic.'],
  ['t07', 'turns', 'Where are U-turns not allowed?', ['On curves and near the top of a hill', 'On any two-lane road', 'In all cities', 'Everywhere in Pennsylvania'], 'Also wherever a NO U-TURN sign is posted.'],
  ['t08', 'turns', 'Your light is green, but vehicles are blocking the intersection. What should you do?', ['Wait until you are sure you can clear the intersection', 'Enter and wait in the middle', 'Honk and squeeze through', 'Drive around them on the shoulder'], 'Never get caught in the middle of an intersection.'],
  ['t09', 'turns', 'You want to pull out, and a car is approaching with its turn signal on. What should you do?', ['Wait until the car actually starts to turn', 'Pull out, since it is turning', 'Pull out slowly', 'Flash your lights and go'], 'The driver may turn somewhere beyond you, or may have forgotten the signal. Motorcycle signals often do not switch off.'],
  ['t10', 'turns', 'When entering a highway from an entrance ramp, you should generally:', ['Accelerate to the speed of traffic', 'Enter slowly to avoid other vehicles', 'Stop first, then enter slowly', 'Enter faster than traffic to get ahead'], 'Signal, find a gap, speed up in the acceleration lane, then merge.'],
  ['t11', 'turns', 'May you pass the vehicle ahead of you in an acceleration lane?', ['No, it is illegal', 'Yes, if it is slow', 'Yes, on the right', 'Yes, with your flashers on'], 'Acceleration lanes are for getting up to speed, not for passing.'],
  ['t12', 'turns', 'Before passing another vehicle you should:', ['Give the proper turn signal to show you are changing lanes', 'Flash your headlights', 'Turn on your four-way flashers', 'Sound your horn'], 'Signal early enough so others know your plans, and check your mirrors and blind spots.'],
  ['t13', 'turns', 'After passing, when is it safe to move back into your lane?', ['When you can see both headlights of the passed vehicle in your rearview mirror', 'As soon as your rear bumper clears it', 'After three seconds', 'When the other driver waves'], 'Signal your return first.'],
  ['t14', 'turns', 'To pass a slower-moving vehicle on a two-lane road you must:', ['Use the lane that belongs to oncoming traffic', 'Use the shoulder', 'Not cross the centre line', 'Flash your lights at oncoming traffic'], 'That is why it needs good judgment: at 45 mph you need about a quarter mile of clear road.'],
  ['t15', 'turns', 'On a two-lane road, you may pass another vehicle on the right when:', ['The driver you are passing is making a left turn', 'The driver is going slower than the speed limit', 'You are on a single-lane entrance ramp', 'Never'], 'Also on roads with two or more marked lanes in each direction.'],
  ['t16', 'turns', 'You may NOT pass when you are within ___ of an intersection, railroad crossing, bridge or tunnel.', ['100 feet', '25 feet', '50 feet', '10 feet'], 'Also not on a curve or hill crest, and never on the shoulder of a multi-lane highway.'],
  ['t17', 'turns', 'When passing on a multi-lane highway:', ['Be sure the passing lane is clear', 'Pass only on the right', 'There is no need to signal', 'Stay beside the other car'], 'Change one lane at a time, and signal every time.'],
  ['t18', 'turns', 'The law gives ___ the right-of-way at intersections.', ['No one', 'Drivers turning left', 'Drivers going straight', 'Drivers turning right'], 'The law only says who must yield. Never insist on the right-of-way.'],
  ['t19', 'turns', 'When no signs, signals or police tell you what to do at an intersection, the law states that:', ['Drivers turning left must yield to drivers going straight', 'Drivers on the right must yield to drivers on the left', 'Drivers going straight must yield to drivers turning left', 'There are no laws about who must yield'], 'And when two arrive from different roads together, the one on the left yields to the one on the right.'],
  ['t20', 'turns', 'Two vehicles reach an intersection with no signs at about the same time, from different roads. Who must yield?', ['The driver coming from the left', 'The driver coming from the right', 'The driver of the smaller vehicle', 'The driver who honks last'], 'Left yields to right.'],
  ['t21', 'turns', 'Drivers entering a roundabout or traffic circle:', ['Must yield to drivers already in it', 'Must always stop before entering', 'Have the right-of-way if they arrive first', 'Have the right-of-way if there are two lanes'], 'Circulating traffic has the right-of-way. Failing to yield is the most frequent cause of roundabout crashes.'],
  ['t22', 'turns', 'In which direction does traffic move in a roundabout?', ['Counter-clockwise', 'Clockwise', 'Either way', 'It depends on the time of day'], 'All turns in and out are right turns. Signal right as you approach your exit.'],
  ['t23', 'turns', 'You are inside a roundabout and an emergency vehicle approaches. What do you do?', ['Exit the roundabout, then pull to the side', 'Stop where you are', 'Keep circling until it has gone', 'Back out'], 'Never stop in a roundabout. If you have not entered yet, pull to the side instead.'],
  ['t24', 'turns', 'You are entering a road from a driveway, alley or private road. You must:', ['Wait until the main road is clear', 'Honk and go', 'Go first, since you are on the right', 'Stop only at night'], 'Also yield to pedestrians on the sidewalk you cross.'],
  ['t25', 'turns', 'Who must yield when a driver is turning and a pedestrian is crossing without a traffic light?', ['The driver', 'The pedestrian', 'Whoever is slower', 'Whoever started last'], 'Drivers yield to pedestrians at intersections and in crosswalks.'],
  ['t26', 'turns', 'At an intersection with a stop sign, you should stop and:', ['Look left first, then right, then left again', 'Look right first, then left, then right again', 'Go when the vehicle ahead goes', 'Check your mirror for tailgaters'], 'Vehicles from the left are closer to you, so check left first and last.'],
  ['t27', 'turns', 'You are waiting to turn left at a multi-lane intersection, and opposing traffic blocks your view. You should:', ['Wait until you can see all the lanes you need to cross', 'Go quickly when the first lane is clear', 'Wait for another driver to wave you across', 'Edge into each lane as it clears'], 'Never start a left turn until every lane you must cross is clear.'],
  ['t28', 'turns', 'The amount of space you need to cross traffic depends on the:', ['Road and weather conditions and oncoming traffic', 'Cars behind you', 'Use of your turn signals', 'Presence of a stop sign'], 'As a guide: about 6 seconds to cross a 30 mph street, 8 to turn right, 9 to turn left onto a major street.'],
  ['t29', 'turns', 'The most important thing to remember about speed and curves is to:', ['Slow down before you enter the curve', 'Slow down at the sharpest part of the curve', 'Accelerate gently before the curve', 'Keep the posted speed through the curve'], 'A car going too fast keeps moving straight, however you steer or brake.'],
  ['t30', 'turns', 'How should you position your car in a curve to the right?', ['Slightly to the right of the centre of your lane', 'On the centre line', 'As far left as possible', 'On the shoulder'], 'In a left curve, keep to the middle of your lane.'],
  ['t31', 'turns', 'The top major crash type for 16-year-old drivers in Pennsylvania is:', ['Single vehicle, run off the road', 'Being sideswiped on an interstate', 'Driving in reverse on a side street', 'Driving on the shoulder of a highway'], 'Usually from going too fast into a curve.'],
  ['t32', 'turns', 'When exiting a highway, you should slow down:', ['Once you have moved into the exit lane', 'On the main road, just before the exit lane', 'When you first see the exit sign', 'Once you see the toll booth'], 'Slowing on the main road invites a rear-end crash.'],
  ['t33', 'turns', 'You want to leave a freeway, but you missed your exit. You should:', ['Go to the next exit and get off there', 'Back up on the shoulder', 'Make a U-turn through the median', 'Stop and wait for help'], 'Stopping, backing up or crossing the median on a highway is illegal and very dangerous.'],
  ['t34', 'turns', 'On a freeway entrance ramp, you should look for a gap in traffic by:', ['Using your mirrors and turning your head to look over your shoulder', 'Looking in the inside mirror only', 'Looking in the side mirror only', 'Looking in both mirrors only'], 'Mirrors alone leave a blind spot.'],
  ['t35', 'turns', '"Highway hypnosis" is a driver condition that can result from:', ['Staring at the roadway for long periods of time', 'Frequent rest stops', 'Too much sleep the night before', 'Short trips on expressways'], 'Keep scanning ahead, behind and around your vehicle.'],
  ['t36', 'turns', 'A highway entrance and an exit share one short "weaving lane". Who must yield?', ['The driver entering the highway', 'The driver exiting the highway', 'The faster driver', 'The driver on the left'], 'Entering traffic yields to exiting traffic in a weave area.'],
  ['t37', 'turns', 'When you park at a curb, how close to it must you be?', ['No more than 12 inches away', 'No more than 24 inches away', 'No more than 6 inches away', 'Touching the curb'], 'With no curb, pull as far off the roadway as possible.'],
  ['t38', 'turns', 'When you must park on the roadway, you should:', ['Use your four-way flashers', 'Park at an angle', 'Keep your turn signal on', 'Leave the engine running'], 'Leave room for passing vehicles and make sure you can be seen from 500 feet in both directions.'],
  ['t39', 'turns', 'You park facing downhill. Which way do you turn the wheels?', ['Completely to the right', 'Completely to the left', 'Straight ahead', 'It does not matter'], 'Downhill, with or without a curb: to the right. Also set the parking brake and shift to Park.'],
  ['t40', 'turns', 'How close to a fire hydrant may you park?', ['No closer than 15 feet', 'No closer than 5 feet', 'No closer than 30 feet', 'No closer than 50 feet'], '15 feet from a hydrant.'],
  ['t41', 'turns', 'How close to a stop sign, yield sign or flashing signal may you park?', ['No closer than 30 feet', 'No closer than 10 feet', 'No closer than 15 feet', 'No closer than 100 feet'], '30 feet from signs and signals at the side of the road.'],
  ['t42', 'turns', 'How close to a crosswalk at an intersection may you park?', ['No closer than 20 feet', 'No closer than 5 feet', 'No closer than 50 feet', 'Right up to it'], '20 feet from a crosswalk at an intersection, and from a fire station driveway.'],
  ['t43', 'turns', 'How close to the nearest rail of a railroad crossing may you park?', ['No closer than 50 feet', 'No closer than 15 feet', 'No closer than 20 feet', 'No closer than 30 feet'], '50 feet from the tracks.'],
  ['t44', 'turns', 'Which of these is a place where you may never park?', ['In front of a driveway', 'On a one-way street', 'Next to a curb', 'Near a streetlight'], 'Also never on a sidewalk, crosswalk, bridge, in a tunnel or intersection, on tracks, or beside another parked car.'],
  ['t45', 'turns', 'You want to use a centre turn lane to turn left. What should you avoid?', ['Entering the lane too soon and driving along in it', 'Signalling before you enter', 'Entering the lane completely', 'Waiting for a gap'], 'The longer you drive in it, the more likely you meet someone head-on.'],

  /* ---------- sharing the road ---------- */
  ['h01', 'share', 'Crashes in work zones are most commonly the result of:', ['Carelessness and speeding', 'Tire blowouts', 'Hydroplaning', 'Driving over wet paint'], 'Fines for certain violations, including speeding, are doubled in active work zones.'],
  ['h02', 'share', 'When driving through a work zone, it is a good safety practice to:', ['Double your usual following distance', 'Halve your following distance', 'Turn on your cruise control', 'Drive close to the vehicle ahead'], 'The most common work zone crash is a rear-end collision.'],
  ['h03', 'share', 'A flagger in a work zone signals you to stop, but the traffic light behind the flagger is green. What do you do?', ['Obey the flagger', 'Obey the light', 'Go slowly past the flagger', 'Honk and wait for a wave'], 'A flagger’s authority overrides conventional traffic control devices.'],
  ['h04', 'share', 'In a work zone you must:', ['Yield to workers and construction vehicles, with your headlights on', 'Stop and ask the workers for directions', 'Slow down to watch the work', 'Cross the solid white line to give room'], 'Stay in your lane, keep moving at a safe speed, and do not use cruise control.'],
  ['h05', 'share', 'If you stop at a railroad crossing with more than one track:', ['Wait until you have a clear view of both tracks', 'Go as soon as the train passes', 'Go when one of the tracks is free', 'Stop on the track to watch for another train'], 'A second train may be hidden behind the first.'],
  ['h06', 'share', 'After a train has passed, you should:', ['Check again for approaching trains and proceed with caution', 'Proceed across the tracks at once', 'Wait for a green light', 'Blow your horn and proceed'], 'Even with one track, do not start across immediately.'],
  ['h07', 'share', 'You are in a line of traffic crossing a railroad track with no signals or gates. You:', ['Must be sure there is room to get all the way across before you start', 'Have the right-of-way over trains', 'May pass slower drivers on the tracks', 'May stop on the tracks if traffic stops'], 'Never get trapped on the tracks. Never pass at a crossing.'],
  ['h08', 'share', 'Your car is trapped on a railroad crossing and a train is coming. What do you do?', ['Leave the car quickly and move as far from the track as you can', 'Stay inside with your seat belt on', 'Try to push the car off', 'Stand on the track and wave at the train'], 'A train cannot stop in time. Get everyone out and away.'],
  ['h09', 'share', 'When you drive through an area where children are playing, you should expect them:', ['To run out in front of you without looking', 'To know when it is safe to cross', 'To stop at the curb first', 'Not to cross without an adult'], 'Always slow down and use extra caution near children.'],
  ['h10', 'share', 'A vehicle ahead of you has stopped in the road and you cannot see why. What should you do?', ['Slow down and do not pass until you are sure no pedestrian is crossing in front of it', 'Pass it quickly on the left', 'Pass it on the right', 'Honk until it moves'], 'It may have stopped for someone crossing.'],
  ['h11', 'share', 'Is it safe to wave a pedestrian across the street in front of your car?', ['No, never wave a pedestrian into traffic', 'Yes, it is polite', 'Yes, at crosswalks', 'Yes, if you flash your lights'], 'Drivers in other lanes may not stop for them.'],
  ['h12', 'share', 'When passing a bicyclist, how much space must you leave?', ['At least 4 feet', 'At least 1 foot', 'At least 2 feet', 'At least 10 feet'], 'Slow down, and move as far left as you safely can.'],
  ['h13', 'share', 'A double yellow line is in the centre, and you need room to pass a bicyclist. What does the law allow?', ['Crossing the double yellow line, if you can do it safely', 'Squeezing past inside your lane', 'Passing on the right shoulder', 'Honking until the cyclist moves over'], 'You may cross the centre line to keep 4 feet of clearance, after checking for oncoming traffic.'],
  ['h14', 'share', 'When passing a bicyclist, you should:', ['Move as far left as possible', 'Blast your horn to alert the bicyclist', 'Remain in the centre of the lane', 'Put on your four-way flashers'], 'Do not honk close to a bicyclist, and do not slow down or stop quickly after you pass.'],
  ['h15', 'share', 'If you are driving behind a motorcycle, you must:', ['Allow the motorcycle to use a complete lane', 'Allow it only half a lane', 'Pass it in the same lane', 'Drive on the shoulder beside it'], 'By law a motorcycle or moped gets one full lane.'],
  ['h16', 'share', 'When travelling behind a motorcycle:', ['Allow at least 4 seconds of following distance', 'Allow at least 2 seconds', 'Allow 2 car lengths', 'Allow 4 motorcycle lengths'], 'The same 4 seconds as for cars, and more in bad weather.'],
  ['h17', 'share', 'Where do most crashes between cars and motorcycles happen?', ['At intersections, when the car turns left in front of the motorcycle', 'On highways, at high speed', 'In parking lots', 'On bridges'], 'The driver should have yielded but did not see the motorcycle.'],
  ['h18', 'share', 'You are following a truck and cannot see its side mirrors. What does that mean?', ['The truck driver cannot see you', 'The truck is about to turn', 'You are at a safe distance', 'The truck has no mirrors'], 'You are in a No-Zone, the blind spot of a truck or bus.'],
  ['h19', 'share', 'When sharing the road with a truck, remember that, in general, trucks:', ['Take longer distances than cars to stop', 'Need less room to turn than cars', 'Need less time to pass on an incline', 'Stop faster because of air brakes'], 'From 65 mph a loaded truck needs at least 600 feet, a car about 400.'],
  ['h20', 'share', 'A truck ahead swings left before making a right turn at an intersection. It is very dangerous to:', ['Try to squeeze between the truck and the curb', 'Brake until the truck has turned', 'Stay behind it', 'Wait for its turn signal to stop'], 'Truck drivers cannot see vehicles squeezing in beside them. Give them room.'],
  ['h21', 'share', 'When a truck driver behind you wants to pass your vehicle, your speed should:', ['Remain steady or decrease', 'Increase', 'Change often', 'Match the truck'], 'Keep to the far side of your lane and do not speed up while it passes.'],
  ['h22', 'share', 'After passing a truck, when should you move back in front of it?', ['When you can see the front of the truck in your rearview mirror', 'As soon as you are past the cab', 'After one second', 'When the truck driver honks'], 'Then keep your speed. Cutting in and slowing down leaves the truck no room to stop.'],
  ['h23', 'share', 'A truck is preparing to back into a loading area and blocks the road. What should you do?', ['Wait: never cross behind a truck that is backing up', 'Drive around behind it quickly', 'Walk behind it', 'Honk so it hurries'], 'Behind the truck you are in its No-Zone.'],
  ['h24', 'share', 'When a school bus has its red lights flashing and its stop arm extended, you must:', ['Stop at least 10 feet away from the bus', 'Drive slowly past the bus', 'Pass if the children have got off', 'Stop only if you are behind it'], 'This applies whether you are behind the bus, coming toward it, or at the intersection where it stopped.'],
  ['h25', 'share', 'The only time you do not have to stop for a school bus with red lights flashing and stop arm out is when you:', ['Are driving on the opposite side of a divided highway', 'See no children', 'Are behind the bus', 'Can safely pass on the left'], 'The highway must be divided by a barrier or median. Still slow down and drive with caution.'],
  ['h26', 'share', 'You stopped for a school bus with its red lights flashing. When may you go?', ['When the red lights stop flashing and the stop arm has been withdrawn', 'When it appears safe', 'When no children are in sight', 'After 10 seconds'], 'And the children have reached a safe place.'],
  ['h27', 'share', 'The amber (yellow) lights on a school bus begin to flash. What does it mean?', ['The bus is preparing to stop', 'The bus is broken down', 'You may pass the bus', 'The bus is empty'], 'Slow down and get ready to stop.'],
  ['h28', 'share', 'What is the penalty for failing to stop for a school bus with its red lights flashing and stop arm out?', ['A 60-day licence suspension, five points and a fine', 'A warning letter', 'Two points only', 'A $25 fine only'], 'One of the heaviest penalties for a single traffic violation.'],
  ['h29', 'share', 'When you hear a fire engine siren, you must:', ['Pull over to the side of the road and stop', 'Slow down until it passes you', 'Drive with your flashers on', 'Speed up and take the nearest exit'], 'Pull as near to the curb as possible and stay clear of intersections.'],
  ['h30', 'share', 'You are on a one-way street and an emergency vehicle with flashing lights is behind you. You:', ['Drive toward the nearest roadside and stop', 'Slow down until it passes', 'Speed up and take the next exit', 'Drive on with your flashers on'], 'On a one-way street the nearest side may be the left.'],
  ['h31', 'share', 'After an emergency vehicle passes you with its siren on, you must:', ['Stay at least 500 feet behind it', 'Follow closely to get through traffic', 'Drive as fast as it does', 'Drive near the curb very slowly'], 'And check that another emergency vehicle is not coming.'],
  ['h32', 'share', 'You approach a police car stopped on the shoulder with its lights flashing. What does the Steer Clear law require?', ['Move into a lane that is not next to it, or slow down if you cannot', 'Stop behind the police car', 'Keep your speed and lane', 'Turn on your flashers and pass on the shoulder'], 'It also covers tow trucks, ambulances and road crews. Fines go up to $250 for a first offence.'],
  ['h33', 'share', 'How should you pass a horse-drawn vehicle or a rider on a horse?', ['Slowly, without blowing your horn, leaving plenty of room', 'Quickly, to get it over with', 'With a long honk as a warning', 'Very close, to save space'], 'Speed and noise can spook the horse.'],
  ['h34', 'share', 'A person is riding in the open bed of a pickup truck. What is the fastest the truck may go?', ['35 mph', '25 mph', '45 mph', '55 mph'], 'And no one under 18 may ride in the bed at all, with few exceptions such as farm work.'],
  ['h35', 'share', 'May you pass a snow plow that is clearing the road?', ['You should not, on either side', 'Yes, on the right', 'Yes, on the left', 'Yes, if you honk first'], 'Plows have wing blades that stick out several feet, and their drivers see very little behind.'],
  ['h36', 'share', 'A funeral procession is going through an intersection and your light turns green. What do you do?', ['Yield until the procession has passed', 'Go, since your light is green', 'Cut in between two of its cars', 'Honk and go slowly'], 'Once the lead vehicle has entered on green, the rest may follow.'],
  ['h37', 'share', 'A right turn on red means stop, look in all directions, and:', ['Give pedestrians time to clear the crosswalk before you turn', 'Turn before the pedestrians reach you', 'Honk so pedestrians wait', 'Turn without looking left'], 'Yield to pedestrians crossing at intersections or in crosswalks.'],

  /* ---------- road rage and emergencies ---------- */
  ['e01', 'emerg', 'If another driver cuts you off in traffic, you should:', ['Ignore the other driver', 'Flash your high beams at the driver', 'Pull alongside and yell', 'Cut the driver off in return'], 'Do not take it personally and do not retaliate.'],
  ['e02', 'emerg', 'If someone is driving aggressively behind you, you should:', ['Try to get out of the aggressive driver’s way', 'Speed up as they pass', 'Block the passing lane', 'Stare at the driver'], 'Avoid eye contact and ignore gestures.'],
  ['e03', 'emerg', 'An aggressive driver is following you. Where should you go?', ['To a police station or a busy place with witnesses', 'Home, as fast as possible', 'To a quiet side street', 'Onto the shoulder to argue'], 'Do not lead them to your home.'],
  ['e04', 'emerg', 'Above 25 mph, you can either brake or steer to avoid a hazard. Which is usually better?', ['Steering around it', 'Braking as hard as possible', 'Doing nothing', 'Shifting to neutral'], 'You can swerve faster than you can stop. Keep both hands on the wheel.'],
  ['e05', 'emerg', 'Where should your hands be on the steering wheel?', ['At 9 and 3 o’clock, or 8 and 4 o’clock', 'At 12 o’clock, one hand', 'At 11 and 1 o’clock', 'At 6 o’clock, one hand'], 'It gives control and keeps your arms clear of the airbag.'],
  ['e06', 'emerg', 'Your car has anti-lock brakes (ABS) and you must stop suddenly. What do you do?', ['Keep firm, continuous pressure on the brake pedal', 'Pump the brake pedal', 'Use the parking brake', 'Brake gently, then release'], 'Do not pump ABS brakes. Noises and pulsing in the pedal are normal.'],
  ['e07', 'emerg', 'Your car does NOT have anti-lock brakes and you must stop suddenly. What do you do?', ['Press and release the brakes repeatedly', 'Slam the brakes and hold them', 'Use only the parking brake', 'Turn off the engine'], 'Slamming the brakes can lock the wheels and make the car skid.'],
  ['e08', 'emerg', 'If the rear of your vehicle starts to skid left, you should:', ['Steer left', 'Steer right', 'Hit your brakes', 'Accelerate'], 'Look and steer where you want to go: the same way the rear is sliding.'],
  ['e09', 'emerg', 'Your car is skidding. Should you use the brakes?', ['No, braking makes the skid worse', 'Yes, brake as hard as you can', 'Yes, pump them fast', 'Yes, with the parking brake'], 'You risk locking the wheels and losing all steering control.'],
  ['e10', 'emerg', 'How much water on a flooded road can make you lose control of your vehicle?', ['As little as 6 inches', 'At least 2 feet', 'At least 3 feet', 'Only moving water above the doors'], 'Two feet of water carries away most vehicles, even SUVs. Find another route.'],
  ['e11', 'emerg', 'A road is closed with signs because of flooding. What happens if you drive around them?', ['Two points and a fine of up to $250', 'Nothing, if you drive slowly', 'A warning', 'A parking ticket'], 'The fine rises to $500, plus rescue costs, if emergency responders must be called.'],
  ['e12', 'emerg', 'Your accelerator (gas pedal) sticks. What should you do?', ['Shift to neutral and use the brakes', 'Reach down and pull the pedal up by hand', 'Turn the key to LOCK', 'Pump the gas pedal hard'], 'Keep your eyes on the road. If you must cut the engine, turn the key to OFF, never LOCK.'],
  ['e13', 'emerg', 'Your brakes suddenly fail in an older car. What should you do first?', ['Shift to low gear and pump the brake pedal quickly', 'Turn the ignition to LOCK', 'Jump out', 'Steer into oncoming traffic'], 'If pumping does not work, use the parking brake and look for a safe place to steer.'],
  ['e14', 'emerg', 'If you have a tire blowout, you should:', ['Let the car slow to a stop', 'Brake hard to stop immediately', 'Let the steering wheel move freely', 'Keep driving to a garage'], 'Hold the wheel tightly, stay off the brake, and ease off the gas.'],
  ['e15', 'emerg', 'Your right wheels drift off the pavement onto a low shoulder. What should you do?', ['Ease off the gas, slow down, then steer gently back', 'Steer sharply back at once', 'Brake hard', 'Speed up to climb back'], 'Slow to under 25 mph first. A sharp turn can throw you into oncoming traffic.'],
  ['e16', 'emerg', 'If an oncoming driver is heading toward you in your lane, you should:', ['Steer right, blow your horn, and brake', 'Steer left, blow your horn, and brake', 'Stay in the centre of your lane and brake', 'Steer right and accelerate'], 'If you swerve left and the other driver corrects at the last moment, you still crash.'],
  ['e17', 'emerg', 'If your car breaks down on a highway, you should:', ['Use your four-way flashers to warn other drivers', 'Flash your headlights at oncoming traffic', 'Sound your horn at passing drivers', 'Stop in your lane and wait'], 'Get as far off the road as you can, and lift the hood.'],
  ['e18', 'emerg', 'If another car is in danger of hitting you, you should:', ['Sound your horn', 'Wave your arms', 'Use your emergency lights', 'Flash your headlights'], 'The horn gets attention instantly.'],
  ['e19', 'emerg', 'How far should you sit from the steering wheel airbag?', ['At least 10 inches', 'At least 2 inches', 'Exactly 5 inches', 'As close as possible'], 'Airbags work with seat belts, not instead of them.'],
  ['e20', 'emerg', 'Carbon monoxide from a car’s exhaust is dangerous because:', ['It is deadly and has no smell', 'It smells very strong', 'It only harms the engine', 'It only forms in summer'], 'Never run the engine in a closed garage. Drowsiness or nausea can be a sign.'],

  /* ---------- you, alcohol and the law ---------- */
  ['l01', 'laws', 'Anything that requires you to ___ could cause you to crash.', ['All of these', 'Take your eyes off the road', 'Take your hands off the wheel', 'Take your attention away from driving'], 'Those are the three kinds of distraction.'],
  ['l02', 'laws', 'Teenage drivers are more likely to be involved in a crash when:', ['They are driving with teenage passengers', 'They are driving with adult passengers', 'They are driving alone', 'They are driving with a pet'], 'Statistics show the risk goes up with other teens in the car.'],
  ['l03', 'laws', 'Drivers who eat and drink while driving:', ['Have trouble controlling their vehicles', 'Make no driving errors', 'Drive better because they are not hungry', 'Have trouble driving slowly'], 'They leave their lane more and brake more often.'],
  ['l04', 'laws', 'Is talking on a hands-free phone a distraction while driving?', ['Yes, hands-free or not', 'No, hands-free is safe', 'Only in cities', 'Only at night'], 'It takes your attention away from the road.'],
  ['l05', 'laws', 'If you begin to feel tired while driving, the best thing to do is:', ['Stop driving', 'Get some coffee', 'Open your window', 'Turn on the radio'], 'You can fall asleep for a few seconds without knowing it.'],
  ['l06', 'laws', 'The effect that lack of sleep has on your driving is the same as:', ['The effect that alcohol has', 'The effect that anger has', 'The effect that amphetamines have', 'The effect of driving with teenagers'], 'Awake for 18 hours is like a .05 blood alcohol level. 24 hours is like .10.'],
  ['l07', 'laws', 'Teenagers should try to get at least ___ of sleep each night to avoid drowsy driving crashes.', ['8 hours', '6 hours', '7 hours', '5 hours'], 'Teens who sleep less than eight hours have a higher crash risk.'],
  ['l08', 'laws', 'If you are under 21, you are considered to be driving under the influence if your blood alcohol level is:', ['.02% or higher', '.05% or higher', '.08% or higher', '.10% or higher'], 'That is Pennsylvania’s Zero Tolerance law.'],
  ['l09', 'laws', 'For a driver 21 or older, at what blood alcohol level is it DUI?', ['.08 or higher', '.02 or higher', '.05 or higher', '.12 or higher'], 'An adult can still be convicted below .08 if stopped for driving erratically.'],
  ['l10', 'laws', 'The Zero Tolerance law reduced the BAC for drivers under 21 from .08% to:', ['.02%', '.00%', '.05%', '.07%'], 'Any measurable alcohol is a problem if you are under 21.'],
  ['l11', 'laws', 'If your blood alcohol level is .04, you:', ['Are 2 to 7 times more likely to crash than a person who has had no alcohol', 'Can be sure you will drive safely', 'Are above the legal limit but fine to drive', 'Should drink coffee before driving'], '.04 is half the adult limit, and already dangerous.'],
  ['l12', 'laws', 'For an average person, how many minutes does the body need to process the alcohol in one drink?', ['60', '15', '30', '90'], 'About one hour per drink.'],
  ['l13', 'laws', '___ limit(s) your concentration, perception, judgment and memory.', ['Even the smallest amount of alcohol', 'Only a level above the legal limit', 'Only a level above .05', 'Alcohol does not'], 'The only safe amount to drink before driving is zero.'],
  ['l14', 'laws', 'As alcohol builds up in your blood, it:', ['Slows down your reactions', 'Makes you feel less confident', 'Decreases your driving errors', 'Leaves the body more quickly'], 'It also makes you feel dangerously confident.'],
  ['l15', 'laws', 'Taking drugs along with alcohol:', ['Increases the risk of causing a crash', 'Is no more dangerous than alcohol alone', 'Lessens the effect of alcohol', 'Has no effect on driving'], 'This includes prescription and over-the-counter medicines.'],
  ['l16', 'laws', 'What sobers you up after drinking?', ['Only time', 'Coffee', 'A cold shower', 'Fresh air'], 'Nothing else lowers your blood alcohol level.'],
  ['l17', 'laws', 'Which of these counts as one drink?', ['12 oz of beer, 5 oz of wine, or 1.5 oz of 80-proof liquor', '24 oz of beer', 'Only liquor counts', '12 oz of wine'], 'Each of the three holds about the same amount of alcohol.'],
  ['l18', 'laws', 'The minimum drinking age in Pennsylvania is:', ['21 years', '18 years', '19 years', '20 years'], 'Under 21 it is illegal to buy, consume, possess or transport alcohol.'],
  ['l19', 'laws', 'It is against the law for anyone under the age of 21 to ___ alcohol.', ['Transport', 'Be in the presence of', 'Wear clothing advertising', 'Look at'], 'Consume, possess, transport or buy: all four are illegal under 21.'],
  ['l20', 'laws', 'A police officer requires you to take a blood, breath or urine test. You:', ['Must take the test, or your licence will be suspended', 'May choose the test you prefer', 'May refuse if you are underage', 'Must first sign a consent form'], 'Implied consent: you agreed to testing by being licensed to drive in Pennsylvania.'],
  ['l21', 'laws', 'You are arrested for DUI and refuse the chemical test. What happens to your licence?', ['It is suspended for one year, even if you are found not guilty', 'Nothing, without a conviction', 'It is suspended for 30 days', 'You get a warning'], 'The refusal suspension comes on top of any DUI suspension.'],
  ['l22', 'laws', 'If you are under 21 and are convicted of DUI, your licence is suspended for a first offence for:', ['1 year', '30 days', '60 days', '6 months'], 'Plus 2 days to 6 months in jail and a fine of $500 to $5,000.'],
  ['l23', 'laws', 'One of the penalties for driving under the influence of alcohol is:', ['Attending Alcohol Highway Safety School', 'A $100 fine', 'A 5-year licence suspension', 'A 12-hour jail sentence'], 'It is required for a first or second offence at any alcohol level.'],
  ['l24', 'laws', 'For a first DUI conviction at any blood alcohol level, you could:', ['Pay a fine of at least $300', 'Lose your licence for up to 5 years', 'Be made to teach a class', 'Get a restricted work licence'], 'The lowest level starts at a $300 fine and six months of probation.'],
  ['l25', 'laws', 'You are under 21 and are convicted of carrying a false ID card. You pay a $500 fine and lose your licence for 90 days:', ['Even if you were not driving', 'Only if you were driving', 'Only if your BAC was .02 or higher', 'Only on a second offence'], 'Underage drinking without driving also brings a 90-day suspension and a fine up to $500.'],
  ['l26', 'laws', 'For police to test the breath, blood or urine of an underage driver, parental consent is:', ['Not required', 'Required from one parent', 'Required from both parents', 'Required under 16 only'], 'The police will notify your parents of the arrest.'],
  ['l27', 'laws', 'At how many points on your driving record does PennDOT begin to take corrective action?', ['6', '3', '10', '12'], 'The first time you choose a written exam (2 points removed) or Driver Improvement School (4 points removed).'],
  ['l28', 'laws', 'How many points are removed from your record for 12 months in a row without a violation?', ['3', '1', '6', 'All of them'], 'Safe driving clears your record over time.'],
  ['l29', 'laws', 'You are under 18 and you collect six or more points. What happens?', ['Your licence is suspended for 90 days', 'You get a warning letter', 'You pay a fine only', 'You must retake the road test only'], 'The same happens for driving 26 mph or more over the limit. A second time: 120 days.'],
  ['l30', 'laws', 'With a learner’s permit under 18, who must ride with you?', ['A licensed driver 21 or older, or a parent, guardian or spouse 18 or older, in the front seat', 'Any licensed driver 16 or older', 'Any adult, in any seat', 'No one, in daylight'], 'The supervising driver must hold a licence and sit in the front.'],
  ['l31', 'laws', 'As a driver under 18, how many passengers may you carry?', ['No more than the number of seat belts', 'As many as fit', 'Two at most', 'None'], 'A junior licence adds limits on passengers under 18 who are not family.'],
  ['l32', 'laws', 'With a junior driver’s licence, when may you not drive unless a parent or guardian is with you?', ['Between 11 PM and 5 AM', 'Between 9 PM and 5 AM', 'Between midnight and 6 AM', 'After sunset'], 'Exceptions need a notarized paper: work, volunteer fire company, charitable service.'],
  ['l33', 'laws', 'In the first six months of a junior licence, how many passengers under 18 who are not family may you carry without a parent?', ['One', 'None', 'Three', 'As many as there are seat belts'], 'After six months with no crash or conviction the limit rises to three.'],
  ['l34', 'laws', 'Before the road test, a driver under 18 must complete at least:', ['65 hours of practice, with 10 at night and 5 in bad weather', '20 hours of practice', '50 hours, all in daylight', '100 hours'], 'And wait six months from the date the permit was issued.'],
  ['l35', 'laws', 'You are driving passengers aged 8 to 17. Where must they wear seat belts?', ['Anywhere in the vehicle', 'Only in the front seat', 'Only on highways', 'Nowhere, it is their choice'], 'The driver is responsible for passengers under 18.'],
  ['l36', 'laws', 'A child under 4 years old must ride in:', ['A federally approved child safety seat', 'A booster seat', 'A seat belt alone', 'An adult’s lap'], 'Ages 4 to 7: a booster seat. Under 2: rear-facing.'],
  ['l37', 'laws', 'If you are stopped by a police officer, you should:', ['Stay in your vehicle with your hands on the steering wheel and wait for the officer', 'Get out and walk to the patrol car', 'Unbuckle and get your papers ready', 'Drive on to a place you prefer'], 'Pull to the right, turn off the engine, lower the window. Hand over your papers when asked.'],
  ['l38', 'laws', 'You are in a crash. When must the police be called?', ['If anyone is hurt or killed, or a vehicle needs to be towed', 'Only if you are at fault', 'Never, insurance handles it', 'Only on highways'], 'Stop, and exchange names, addresses, registration and insurance details.'],
  ['l39', 'laws', 'You hit a parked car and cannot find its owner. What must you do?', ['Leave a note where it can be seen, and call the police', 'Drive away', 'Wait one minute, then leave', 'Tell the next person who walks by'], 'The note gives the date and time, your name and a phone number.'],
  ['l40', 'laws', 'Your vehicle was without insurance and you drove it anyway. What happens?', ['Your registration and your licence are each suspended for three months', 'You get a warning', 'Only a small fine', 'Your car is taken for a year'], 'Pennsylvania requires liability insurance at all times.'],
  ['l41', 'laws', 'What is the fine for texting while driving in Pennsylvania?', ['$50', '$10', '$25', '$500'], 'Texting, emailing and browsing while driving are banned.'],
  ['l42', 'laws', 'You move to a new address. How soon must you tell PennDOT?', ['Within 15 days', 'Within 60 days', 'Within 6 months', 'At your next renewal'], 'The same goes for a change of name.'],
  ['l43', 'laws', 'How often must your vehicle pass a safety inspection?', ['Every 12 months', 'Every 6 months', 'Every 2 years', 'Only when it is sold'], 'The sticker shows when the next inspection is due.'],
  ['l44', 'laws', 'A driver is convicted of fleeing or trying to elude the police. What is the penalty?', ['A one-year suspension and a $500 fine', 'Two points', 'A 15-day suspension', 'A warning'], 'It can also mean prison.'],
].map(([id, t, q, a, why, sign]) => ({ id, t, q, a, why, sign }));
